pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    let mut out: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        if maxsplit == 0 {
            // No splitting at all
            out.push(vec![s]);
            continue;
        }

        if s.is_empty() {
            // Explicitly required behavior
            out.push(vec![String::new()]);
            continue;
        }

        // Right split with at most `maxsplit` splits => at most `maxsplit + 1` parts.
        // Rust's `rsplitn(k, sep)` yields at most `k` parts, i.e., `k - 1` splits.
        let parts: Vec<String> = s
            .rsplitn(maxsplit as usize + 1, &sep)
            .map(|p| p.to_string())
            .collect();

        // `rsplitn` returns parts from right to left; reverse to match natural left-to-right order.
        let mut parts = parts;
        parts.reverse();

        // Ensure each inner list is non-empty (should always hold).
        if parts.is_empty() {
            out.push(vec![s]);
        } else {
            out.push(parts);
        }
    }

    out
}